WITH with_last AS (SELECT s.*, x.transaction_txn_type, x.transaction_merchant FROM accounts s LEFT JOIN LATERAL (SELECT c.txn_type AS transaction_txn_type, c.merchant AS transaction_merchant FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT account_type, STDDEV_SAMP(balance) AS balance_stddev, SORT_ARRAY(COLLECT_SET(transaction_txn_type)) AS transaction_txn_type_list, ROUND(AVG(balance), 2) AS avg_balance FROM with_last GROUP BY 1 HAVING avg_balance > 0 ORDER BY account_type DESC
